package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.SheetArchivedException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The first step of every change: a viewer, and any change to an archived sheet, is refused before
 *  anything is read or written. */
public class RefuseViewer {
    public void refuse(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by, RoleRepository roles,
            SheetRepository sheets) throws ViewerRefusedException, SheetArchivedException {
        if (sheets.isArchived(sheetId.trim())) {
            throw new SheetArchivedException("The sheet is archived");
        }
        if (Role.VIEWER.equals(roles.roleOf(sheetId.trim(), by == null ? "" : by))) {
            throw new ViewerRefusedException("A viewer may change nothing");
        }
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSheetToday {
    public void validate(@RequestBody SheetTodayRequest request, Out<LocalDate> today)
            throws InvalidSheetTodayException {
        String value = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(value));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetTodayException("Not a date: " + value);
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Reopens a closed or soft-closed period: its due-total is live again. Refused for a role the permission matrix does not let reopen (by default
 *  anyone but a steward), and when
 *  the period is not closed or is locked. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings, Out<Period> period) throws InvalidPeriodException, PeriodReopenException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (!Permissions.allows(id, by, Permissions.REOPEN, roles, settings)) {
            throw new PeriodReopenException("Your role may not reopen a period");
        }
        if (found.locked()) {
            throw new PeriodReopenException("The period is locked");
        }
        if (!found.fixed()) {
            throw new PeriodReopenException("The period is not closed");
        }
        period.set(periods.reopen(found));
    }
}

